/*-- CSS Variables --*/ :root{ --body-font:$(main.font.family); --menu-font:$(menu.font.family); --title-font:$(title.font.family); --meta-font:$(meta.font.family); --text-font:$(text.font.family); --body-bg-color:$(body.background.color); --body-bg:$(body.background); --outer-bg:$(outer.bg); --main-color:$(main.color); --title-color:$(title.color); --title-hover-color:$(title.hover.color); --meta-color:$(meta.color); --text-color:$(text.color); --tag-bg:$(tag.bg); --tag-color:$(tag.color); --header-bg:$(header.bg); --header-color:$(header.color); --header-hover-color:$(header.hover.color); --header-text-color:$(header.text.color); --main-nav-bg:$(menu.bg); --main-nav-color:$(menu.color); --main-nav-active-bg:$(menu.link.active.bg); --main-nav-active-color:$(menu.link.active.color); --main-nav-hover-bg:$(menu.link.hover.bg); --main-nav-hover-color:$(menu.link.hover.color); --submenu-bg:$(submenu.bg); --submenu-color:$(submenu.color); --submenu-hover-color:$(submenu.hover.color); --megamenu-bg:$(megamenu.bg); --megamenu-color:$(megamenu.color); --megamenu-hover-color:$(megamenu.hover.color); --mobilemenu-bg:$(mmenu.bg); --mobilemenu-color:$(mmenu.color); --mobilemenu-hover-color:$(mmenu.hover.color); --widget-title-color:$(wtitle.color); --widget-title-dot:$(wtitledot.bg); --post-title-color:$(post.title.color); --post-title-hover-color:$(post.title.hover.color); --post-text-color:$(post.text.color); --footer-bg:$(footer.bg); --footer-color:$(footer.color); --footer-hover-color:$(footer.hover.color); --footer-text-color:$(footer.text.color); --footerbar-bg:$(footerbar.bg); --footerbar-color:$(footerbar.color); --footerbar-hover-color:$(footerbar.hover.color); --cookie-bg:$(cookie.bg); --cookie-color:$(cookie.color); --button-bg:$(button.bg); --button-color:$(button.color); --button-hover-bg:$(button.hover.bg); --button-hover-color:$(button.hover.color); --border-color:rgba(155,155,155,0.08); --bb-color:rgba(0,0,0,0.1); } html[data-theme=dark]{ --body-bg-color:$(body.darkmode.bg); --body-bg:$(body.darkmode.bg); --outer-bg:#161D1F; --main-color:$(main.color); --title-color:#f4f4f4; --title-hover-color:$(main.color); --meta-color:#dddddd; --text-color:#bbbbbb; --tag-bg:$(main.color); --tag-color:#ffffff; --header-bg:#0F1618; --header-color:#f4f4f4; --header-hover-color:$(main.color); --header-text-color:#bbbbbb; --main-nav-bg:$(main.color); --main-nav-color:#ffffff; --main-nav-active-bg:rgba(255,255,255,0.1); --main-nav-active-color:#ffffff; --main-nav-hover-bg:rgba(255,255,255,0.1); --main-nav-hover-color:#ffffff; --submenu-bg:#0F1618; --submenu-color:#f4f4f4; --submenu-hover-color:$(main.color); --megamenu-bg:#0F1618; --megamenu-color:#f4f4f4; --megamenu-hover-color:$(main.color); --mobilemenu-bg:#161D1F; --mobilemenu-color:#f4f4f4; --mobilemenu-hover-color:$(main.color); --widget-title-color:#f4f4f4; --widget-title-dot:$(main.color); --post-title-color:#f4f4f4; --post-title-hover-color:$(main.color); --post-text-color:#bbbbbb; --footer-bg:#0F1618; --footer-color:#f4f4f4; --footer-hover-color:$(main.color); --footer-text-color:#bbbbbb; --footerbar-bg:#0c1213; --footerbar-color:#f4f4f4; --footerbar-hover-color:$(main.color); --cookie-bg:#0F1618; --cookie-color:#bbbbbb; --button-bg:$(main.color); --button-color:#ffffff; --button-hover-bg:$(button.hover.bg); --button-hover-color:$(button.hover.color); --border-color:rgba(155,155,155,0.08); --bb-color:rgba(0,0,0,0.1); } html.rtl{ --body-font:'Tajawal',Arial,sans-serif; --menu-font:'Tajawal',Arial,sans-serif; --title-font:'Tajawal',Arial,sans-serif; --meta-font:'Tajawal',Arial,sans-serif; --text-font:'Tajawal',Arial,sans-serif; } html[data-theme=dark] .main-logo img { -webkit-filter: invert(1); filter: invert(1); } /*-- Reset CSS --*/ a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;margin:0;border:0;outline:0;vertical-align:baseline;background:0 0;text-decoration:none}dl,ul{list-style-position:inside;list-style:none}ul li{list-style:none}caption{text-align:center}img{border:none;position:relative}a,a:visited{text-decoration:none}.clearfix{clear:both}.section,.widget,.widget ul{margin:0;padding:0}a{color:var(--main-color)}a img{border:0}abbr{text-decoration:none}.CSS_LIGHTBOX{z-index:999999!important}.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{opacity:0}.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}#Navbar1,#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}.center{display:table;margin:0 auto;position:relative}.widget > h2,.widget > h3{display:none}.widget iframe,.widget img{max-width:100%}button,input,select,textarea{font-family:var(--body-font);-webkit-appearance:none;-moz-appearance:none;appearance:none;outline:none;border-radius:0}
/*-- Style CSS --*/ *{ box-sizing:border-box; text-rendering:optimizeLegibility; -webkit-font-smoothing:antialiased } html{ position:relative; margin:0 } body{ position:relative; background:var(--body-bg); background-color:var(--body-bg-color); font-family:var(--body-font); font-size:14px; color:var(--text-color); font-weight:400; font-style:normal; line-height:1.4em; word-wrap:break-word; margin:0; padding:0 } body.is-cover{ background-attachment:fixed; background-size:cover; background-position:center center; background-repeat:no-repeat } .rtl{ direction:rtl } h1,h2,h3,h4,h5,h6{ font-family:var(--title-font); font-weight:700 } a,input,button{ transition:all .0s ease } #outer-wrapper{ position:relative; overflow:hidden; width:100%; max-width:100%; background-color:var(--outer-bg); margin:0 auto; padding:0 } .is-boxed #outer-wrapper{ width:$(row.width + 50px); max-width:100%; box-shadow:0 0 20px rgba(0,0,0,0.1) } .container{ position:relative } .row-x1{ width:$(row.width) } .flex-center{ display:flex; justify-content:center } #content-wrapper{ position:relative; float:left; width:100%; overflow:hidden; padding:30px 0; margin:0; border-top:0 } .theiaStickySidebarIfy:before,.theiaStickySidebarIfy:after{ content:''; display:table; clear:both } #main-wrapper{ position:relative; float:left; width:calc(100% - $(sidebar.width + 30px)); padding:0 } .is-left #main-wrapper,.rtl #main-wrapper{ float:right } #sidebar-wrapper{ position:relative; float:right; width:$(sidebar.width); padding:0 } .is-left #sidebar-wrapper,.rtl #sidebar-wrapper{ float:left } .btn{ position:relative; border:0; border-radius:2px } .entry-image-wrap,.comments .avatar-image-container{ overflow:hidden; background-color:rgba(155,155,155,0.08); z-index:5; color:transparent!important; transition:opacity .17s ease } .entry-thumb{ display:block; position:relative; width:100%; height:100%; background-size:cover; background-position:center center; background-repeat:no-repeat; z-index:1; opacity:0; transition:opacity .35s ease,filter 0s ease } .entry-thumb.lazy-ify{ opacity:1 } .entry-image-wrap:hover .entry-thumb,.entry-inner:hover .entry-image-wrap .entry-thumb{ filter:brightness(1.05) } .before-mask:before{ content:''; position:absolute; left:0; right:0; bottom:0; height:70%; background-image:linear-gradient(to bottom,transparent,rgba(0,0,0,0.5)); -webkit-backface-visibility:hidden; backface-visibility:hidden; z-index:2; opacity:1; margin:0; transition:opacity .25s ease } .entry-image-wrap.is-video:after{ position:absolute; display:flex; align-items:center; justify-content:center; content:'\f04b'; top:50%; right:50%; background-color:rgba(0,0,0,0.5); width:44px; height:30px; font-family:'Font Awesome 5 Free'; font-size:12px; color:#fff; font-weight:900; z-index:5; transform:translate(50%,-50%); margin:0; border-radius:8px; transition:background .17s ease } .entry-image-wrap.is-video.c-ply:after{ transform:translate(50%,-50%) scale(1.2) } .entry-inner .entry-image-wrap.is-video:not(.c-ply):after{ top:15px; right:15px; transform:translate(0%,0%) } .rtl .entry-inner .entry-image-wrap.is-video:not(.c-ply):after{ left:15px; right:unset } .entry-image-wrap.is-video:hover:after,.entry-inner:hover .entry-image-wrap.is-video:after{ background-color:var(--main-color) } .entry-tag{ position:absolute; top:10px; left:10px; height:18px; background-color:var(--tag-bg); font-size:11px; color:var(--tag-color); font-weight:400; line-height:19px; text-transform:uppercase; z-index:5; padding:0 6px; margin:0; border-radius:2px } .rtl .entry-tag{ left:unset; right:10px } .entry-info{ position:absolute; left:0; bottom:0; width:100%; background:linear-gradient(to bottom,transparent,rgba(0,0,0,0.8)); overflow:hidden; z-index:5; display:flex; flex-direction:column; padding:15px } .entry-info .entry-title{ color:#fff; text-shadow:0 1px 2px rgba(0,0,0,0.5) } .entry-info .entry-meta{ color:#ccc } .entry-info .entry-meta .author-name{ color:#ddd } .entry-title{ color:var(--post-title-color); font-we